+import * as React from 'react';
+import PropTypes from 'prop-types';
+import clsx from 'clsx';
+import { deepmerge } from '@material-ui/utils';
+import { unstable_extendSxProp as extendSxProp } from '@material-ui/system';
+import { unstable_composeClasses as composeClasses } from '@material-ui/unstyled';
+import experimentalStyled from '../styles/experimentalStyled';
+import useThemeProps from '../styles/useThemeProps';
+import stackClasses, { getStackUtilityClass } from './stackClasses';
+
+const overridesResolver = (props, styles) => {
+  const { styleProps } = props;
+
+  return deepmerge(
+    {
+      ...(styleProps.direction !== 'column' &&
+        styles[`direction-xs-${String(styleProps.direction)}`]),
+      ...(styleProps.spacing !== 0 && styles[`spacing-xs-${String(styleProps.spacing)}`]),
+    },
+    styles.root || {},
+  );
+};
+
+const StackRoot = experimentalStyled(
+  'div',
+  {},
+  { name: 'MuiStack', slot: 'Root', overridesResolver },
+)(({ theme, styleProps }) => {
+  const { direction, spacing } = styleProps;
+
+  const styles = {
+    display: 'flex',
+    flexDirection: direction,
+  };
+
+  if (spacing !== 0) {
+    const themeSpacing = theme.spacing(spacing);
+
+    if (themeSpacing !== '0px') {
+      if (direction === 'column' || direction === 'column-reverse') {
+        styles['& > :not(style) ~ :not(style)'] = {
+          marginTop: themeSpacing,
+        };
+      } else {
+        styles['& > :not(style) ~ :not(style)'] = {
+          marginLeft: themeSpacing,
+        };
+      }
+    }
+  }
+
+  return styles;
+});
+
+const useUtilityClasses = (styleProps) => {
+  const { classes, direction, spacing } = styleProps;
+
+  const slots = {
+    root: [
+      'root',
+      direction !== 'column' && `direction-xs-${String(direction)}`,
+      spacing !== 0 && `spacing-xs-${String(spacing)}`,
+    ],
+  };
+
+  return composeClasses(slots, getStackUtilityClass, classes);
+};
+
+const Stack = React.forwardRef(function Stack(inProps, ref) {
+  const themeProps = useThemeProps({ props: inProps, name: 'MuiStack' });
+  const props = extendSxProp(themeProps);
+  const {
+    className,
+    component = 'div',
+    direction = 'column',
+    spacing = 0,
+    ...other
+  } = props;
+
+  const styleProps = {
+    ...props,
+    direction,
+    spacing,
+  };
+
+  const classes = useUtilityClasses(styleProps);
+
+  return (
+    <StackRoot
+      styleProps={styleProps}
+      className={clsx(classes.root, className)}
+      as={component}
+      ref={ref}
+      {...other}
+    />
+  );
+});
