@@ -991,6 +991,44 @@ static LLVMTypeRef ffi_return_type(compile_t* c, reach_type_t* t,
   }
 }

+static LLVMTypeRef ffi_declared_type(compile_t* c, reach_type_t* t,
+  ast_t* args, bool intrinsic)
+{
+  ast_t* last_arg = ast_childlast(args);
+
+  if((last_arg != NULL) && (ast_id(last_arg) == TK_ELLIPSIS))
+  {
+    LLVMTypeRef r_type = ffi_return_type(c, t, false);
+    return LLVMFunctionType(r_type, NULL, 0, true);
+  }
+
+  int count = (int)ast_childcount(args);
+  size_t buf_size = count * sizeof(LLVMTypeRef);
+  LLVMTypeRef* f_params = (LLVMTypeRef*)ponyint_pool_alloc_size(buf_size);
+  count = 0;
+
+  ast_t* arg = ast_child(args);
+
+  while(arg != NULL)
+  {
+    ast_t* p_type = ast_type(arg);
+
+    if(p_type == NULL)
+      p_type = ast_childidx(arg, 1);
+
+    reach_type_t* pt = reach_type(c->reach, p_type);
+    pony_assert(pt != NULL);
+    f_params[count++] = ((compile_type_t*)pt->c_type)->use_type;
+    arg = ast_sibling(arg);
+  }
+
+  LLVMTypeRef r_type = ffi_return_type(c, t, intrinsic);
+  LLVMTypeRef f_type = LLVMFunctionType(r_type, f_params, count, false);
+
+  ponyint_pool_free_size(buf_size, f_params);
+  return f_type;
+}
+
 static LLVMValueRef declare_ffi_vararg(compile_t* c, const char* f_name,
   reach_type_t* t)
 {
@@ -1097,6 +1135,28 @@ LLVMValueRef gen_ffi(compile_t* c, ast_t* ast)
       // Make it varargs.
       func = declare_ffi_vararg(c, f_name, t);
     }
+  } else {
+    // The function already exists in this module. If this call has a
+    // declaration, make sure the existing signature is compatible with it.
+    // Declaring the same function with incompatible signatures in different
+    // packages would otherwise generate invalid calls, which can crash both
+    // ponyc and LLVM.
+    ast_t* decl = (ast_t*)ast_data(ast);
+
+    if(decl != NULL)
+    {
+      ast_t* decl_params = ast_childidx(decl, 2);
+      LLVMTypeRef expected = ffi_declared_type(c, t, decl_params, false);
+      LLVMTypeRef actual = LLVMGetElementType(LLVMTypeOf(func));
+
+      if(actual != expected)
+      {
+        ast_error(c->opt->check.errors, ast,
+          "FFI function '%s' was declared with an incompatible signature",
+          f_name);
+        return NULL;
+      }
+    }
   }

