+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+import { MatrixEvent } from "matrix-js-sdk/src/matrix";
+
+import { VoiceBroadcastRecording, VoiceBroadcastRecordingEvent } from "../models/VoiceBroadcastRecording";
+
+export enum VoiceBroadcastRecordingsStoreEvent {
+    RecordingAdded = "recording_added",
+    RecordingRemoved = "recording_removed",
+}
+
+type EventHandlerMap = {
+    [VoiceBroadcastRecordingsStoreEvent.RecordingAdded]: (recording: VoiceBroadcastRecording) => void;
+    [VoiceBroadcastRecordingsStoreEvent.RecordingRemoved]: (recording: VoiceBroadcastRecording) => void;
+};
+
+export class VoiceBroadcastRecordingsStore
+    extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvent, EventHandlerMap> {
+
+    private recordings: Map<string, VoiceBroadcastRecording> = new Map();
+
+    public getByEventId(eventId: string): VoiceBroadcastRecording | undefined {
+        return this.recordings.get(eventId);
+    }
+
+    public add(recording: VoiceBroadcastRecording): void {
+        this.recordings.set(recording.eventId, recording);
+        this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingAdded, recording);
+    }
+
+    public remove(recording: VoiceBroadcastRecording): void {
+        this.recordings.delete(recording.eventId);
+        this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingRemoved, recording);
+    }
+
+    public destroy(): void {
+        this.recordings.forEach((recording) => recording.destroy());
+        this.recordings.clear();
+        this.removeAllListeners();
+    }
+}
